document.addEventListener("DOMContentLoaded",function(){var y=document.getElementById("yr");if(y)y.textContent=new Date().getFullYear();function msg(){var g=function(i){var el=document.getElementById(i);return el?el.value.trim():""};var p=document.getElementById("privacyConsent")?document.getElementById("privacyConsent").checked:"No";return"StayCRS demo request\n\nName: "+g("n")+"\nCountry: "+g("c")+"\nHotel: "+g("h")+"\nEmail: "+g("e")+"\nPhone: "+g("p")+"\nRooms: "+g("r")+"\nInterested in: "+g("i")+"\nPrivacy Consent: "+p}var df=document.getElementById("demoForm");if(df){df.addEventListener("submit",function(ev){ev.preventDefault();window.location.href="mailto:info@crscentral.com?subject="+encodeURIComponent("StayCRS demo request")+"&body="+encodeURIComponent(msg());var th=document.getElementById("thanks");if(th)th.style.display="inline"})}var wa=document.getElementById("wa");if(wa){wa.addEventListener("click",function(){this.href="https://wa.me/919121773501?text="+encodeURIComponent(msg())})}var tb=document.querySelector(".menu-toggle-btn"),ln=document.querySelector(".links");if(tb&&ln){tb.addEventListener("click",function(e){e.stopPropagation();ln.classList.toggle("mobile-open");tb.innerHTML=ln.classList.contains("mobile-open")?"✕":"☰"});document.addEventListener("click",function(e){if(!ln.contains(e.target)&&e.target!==tb){ln.classList.remove("mobile-open");tb.innerHTML="☰"}})}});
